# Full function context (WaRF function-aware diff)

std::string getTempPath()
{
#       if   defined(_WIN32)
    TCHAR _temp[MAX_PATH];
    (void)GetTempPath(MAX_PATH, // length of the buffer
            _temp);// buffer for path
    return std::string(_temp);
#       else
    char * _temp;
#       if defined(__APPLE__)
    _temp = getenv ("TMPDIR");
#       elif defined(__unix)
    _temp = getenv("TEMP");
#       endif

    std::string path;
    if (_temp != NULL)
    {
        path = _temp;
        std::free(_temp);
        return path;
    }

    _temp = getcwd(NULL, 0);
    path = _temp;
    std::free(_temp);
    return path;
#       endif
}

